using System;
using System.Linq;
using UnityEngine;
public static class UturnTests {
 static void Check(bool value,string message){if(!value)throw new Exception("UTURN: "+message);}
 static RoadMapLane Lane(string id,float x,float z,float dx,float dz){return new RoadMapLane{id=id,sourceId="road",status="provisional",ruleId="junction",fromNode=id+":a",toNode=id+":b",points=new[]{new MapPoint{x=x,z=z},new MapPoint{x=x+dx,z=z+dz}},heights=new[]{0f,0f}};}
 static void ObserverCase(TrafficSystem traffic,TrafficJunction junction,RoadMapLane from,RoadMapLane join){junction.halfWidth[0]=8;
  var sessionObject=new GameObject("Uturn observer session");sessionObject.SetActive(false);var session=sessionObject.AddComponent<DriveSession>();session.traffic=traffic;session.business=sessionObject.AddComponent<BusinessProgress>();session.business.enabledCampaign=false;session.business.ledger=new EconomyLedger(new PrototypeSettings());session.jobs=sessionObject.AddComponent<PassengerJobs>();
  var taxiObject=new GameObject("Uturn observer taxi");taxiObject.SetActive(false);var taxi=taxiObject.AddComponent<TaxiController>();taxi.body=taxiObject.AddComponent<Rigidbody>();session.taxi=taxi;session.assisted=taxiObject.AddComponent<AssistedDriveController>();session.manners=taxiObject.AddComponent<DrivingManners>();session.manners.session=session;session.law=taxiObject.AddComponent<DrivingLaw>();session.law.session=session;
  var tick=typeof(DrivingLaw).GetMethod("FixedUpdate",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);var direction=traffic.AxisDirection(junction,0);var right=TrafficSystem.Right(direction);float side=Vector3.Dot(from.points.Last().V()-junction.center,right);var line=traffic.StopPosition(junction,0,1)+right*side;var before=line-direction*.5f;var after=line+direction*.5f;
  Action<Vector3,Vector3> move=(point,heading)=>{taxi.transform.position=point-heading*2;taxi.transform.forward=heading;tick.Invoke(session.law,null);};
  move(before,direction);move(after,direction);session.manners.CheckSignal(before,after);var previous=after;
  for(int i=0;i<join.points.Length;i+=4){var point=join.points[i].V();var heading=(join.points[Math.Min(i+1,join.points.Length-1)].V()-join.points[Math.Max(0,i-1)].V()).normalized;move(point,heading);session.manners.CheckSignal(previous,point);previous=point;}
  for(int i=1;i<=8;i++){var point=join.points.Last().V()+Vector3.back*i*2;move(point,Vector3.back);session.manners.CheckSignal(previous,point);previous=point;}
  Check(session.law.ledger.Events.Any(e=>e.action=="유턴"&&e.Deduction==0),"pedestrian phase U-turn law classified and compliant · events="+string.Join(",",session.law.ledger.Events.Select(e=>e.action+":"+e.Deduction).ToArray())+" · side="+side+" width="+junction.halfWidth[0]);Check(session.manners.ledger.Score==100,"pedestrian phase U-turn does not lose driving score");UnityEngine.Object.DestroyImmediate(taxiObject);UnityEngine.Object.DestroyImmediate(sessionObject);
 } static void EditorRejectsInvalidConnection(RoadMapLane from){
  var destination=Lane("short-target",77,80,0,-60);var document=new RoadMapDocument{lanes=new[]{from,destination}};var owner=new GameObject("Uturn editor rejection");owner.SetActive(false);var editor=owner.AddComponent<RoadMapEditor>();editor.document=document;editor.history=new RoadMapEditHistory(document);var fields=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;typeof(RoadMapEditor).GetField("easyAction",fields).SetValue(editor,"connect");typeof(RoadMapEditor).GetField("easySource",fields).SetValue(editor,from.id);typeof(RoadMapEditor).GetField("connectTurn",fields).SetValue(editor,-2);editor.EasyMapClick(new Vector3(77,0,50));
  Check(editor.CurrentInteraction=="connect"&&editor.document.lanes.Length==2&&editor.document.revision==1,"invalid editor U-turn keeps target selection and document unchanged");var message=(string)typeof(RoadMapEditor).GetField("notice",fields).GetValue(editor);Check(message.Contains("간격")&&!message.Contains("출구 연결 완료"),"invalid editor U-turn reports geometry error");UnityEngine.Object.DestroyImmediate(owner);
 }
 public static void Run(){var from=Lane("in",80,20,0,60);var target=Lane("out",68,80,0,-60);var doc=new RoadMapDocument{lanes=new[]{from,target}};
 string id=RoadMapAuthoringOperations.Connect(doc,from.id,target.id,-2);var join=doc.lanes.First(l=>l.id==id);Check(join.turn==-2&&from.next.Contains(id)&&join.next.SequenceEqual(new[]{target.id}),"explicit U-turn chain");Check(Vector3.Distance(join.points[0].V(),from.points.Last().V())<.001f&&Vector3.Distance(join.points.Last().V(),target.points[0].V())<.001f,"continuous endpoints");Check(Vector3.Dot((join.points[1].V()-join.points[0].V()).normalized,Vector3.forward)>.98f&&Vector3.Dot((join.points.Last().V()-join.points[join.points.Length-2].V()).normalized,Vector3.back)>.98f,"continuous headings");

 bool rejected=false;target.points[0].x=77;try{RoadMapAuthoringOperations.Connect(doc,from.id,target.id,-2);}catch(ArgumentException){rejected=true;}Check(rejected,"short radius rejected");target.points[0].x=68;EditorRejectsInvalidConnection(from);target.disabled=true;rejected=false;try{RoadMapAuthoringOperations.Connect(doc,from.id,target.id,-2);}catch(ArgumentException){rejected=true;}Check(rejected,"disabled target rejected");target.disabled=false;
 var map=new MapData{mapId="uturn-test",hybrid=true,width=200,depth=200,roads=new MapRoad[0],buildings=new MapBuilding[0],targets=new[]{new MapTarget{x=74,z=90},new MapTarget{x=74,z=120}},areas=new MapArea[0],landmarks=new MapLandmark[0],stops=new MapStop[0],hdEdges=new HdEdge[0],hdMarks=new HdMark[0],hdTrials=new HdTrialCase[0],hdSignals=new MapPoint[0],junctionRules=new[]{new HybridJunctionRule{id="junction",x=74,z=90,dx=0,dz=1,signalMode=2,crosswalk=true}}};
 doc.mapId=map.mapId;doc.baseHash=RoadMapRuntime.Hash(map);var errors=RoadMapValidator.Validate(map,doc).Where(x=>x.error).ToArray();Check(errors.Any(e=>e.message.Contains("유턴")),"missing condition rejected");
 doc.facilities=new[]{new RoadMapFacility{id="condition",kind="sign",type=UturnMovement.LeftOrPedestrianGreen,laneId=from.id,junctionId="junction",rule=true,x=85,z=75}};
 errors=RoadMapValidator.Validate(map,doc).Where(x=>x.error).ToArray();Check(errors.Length==0,"valid U-turn accepted: "+string.Join(" / ",errors.Select(e=>e.ToString()).ToArray()));
 var composed=RoadMapComposer.Compose(map,doc);var graph=new HdRoadGraph(composed);var route=graph.Route(0,20,1,20);Check(route!=null&&route.edges.Contains(2),"routing uses explicit U-turn");Check(graph.Instruction(route,0).Contains("유턴"),"navigation U-turn label");
 Check(LaneDirectionPaint.Layout(composed).Any(a=>(a.turns&LaneDirectionPaint.Uturn)!=0)&&RoadMapEasySelection.TurnLabel(8).Contains("유턴"),"U-turn glyph distinct from left");
 var parsed=RoadMapDocument.Parse(doc.ToJson());Check(parsed.lanes.First(l=>l.id==id).turn==-2&&parsed.facilities[0].type==UturnMovement.LeftOrPedestrianGreen,"roundtrip preserves turn and condition");
 foreach(var condition in UturnMovement.Conditions){Check(!UturnMovement.Allows(condition,true,true,false),"all conditions yield");Check(UturnMovement.Allows(condition,true,true,true),"allowed green conditions");}Check(!UturnMovement.Allows(UturnMovement.LeftGreen,false,true,true)&&!UturnMovement.Allows(UturnMovement.PedestrianGreen,true,false,true),"conditions not conflated");Check(UturnMovement.Allows(UturnMovement.LeftOrPedestrianGreen,false,true,true)&&!UturnMovement.Allows("unsupported",true,true,true),"OR condition and unknown rejection");
 Check(RoadMapValidator.Conflict(new RoadMapSignalGroup{turn=-2},new RoadMapSignalGroup{turn=0}),"U-turn signal conflicts with same approach");

 doc.signals=new[]{new RoadMapSignalProgram{junctionId="junction",groups=new[]{new RoadMapSignalGroup{id="left",turn=-1},new RoadMapSignalGroup{id="walk",pedestrian=true},new RoadMapSignalGroup{id="other",axis=1}},stages=new[]{new RoadMapStage{green=10,yellow=2,clearance=1,groups=new[]{"left"}},new RoadMapStage{green=10,yellow=0,clearance=1,groups=new[]{"walk"}},new RoadMapStage{green=10,yellow=2,clearance=1,groups=new[]{"other"}}}}};
 composed=RoadMapComposer.Compose(map,doc);var root=new GameObject("Uturn runtime test");var traffic=root.AddComponent<TrafficSystem>();traffic.Build(composed,false);traffic.manualClock=true;var junction=traffic.junctions.First(j=>j.name=="junction");traffic.manualTime=1;Check(traffic.UturnPermitted(junction,0,1,from.id),"left green phase admits condition");traffic.manualTime=14;Check(traffic.UturnPermitted(junction,0,1,from.id),"pedestrian green phase admits condition");traffic.manualTime=25;Check(!traffic.UturnPermitted(junction,0,1,from.id),"other phase blocks condition");traffic.manualTime=11;Check(!traffic.UturnPermitted(junction,0,1,from.id),"yellow blocks");traffic.manualTime=1;
 var trafficRoute=new TrafficRoute{graphPath=route};trafficRoute.SetPoints(route.path.points);var stop=new TrafficStop{junction=junction,axis=0,turn=-2,distance=39,exitDistance=route.ends[1]+3};trafficRoute.stops.Add(stop);var subject=new GameObject("Uturn subject").AddComponent<TrafficCar>();subject.route=trafficRoute;subject.distance=39;subject.transform.position=trafficRoute.Position(39);subject.transform.forward=trafficRoute.Tangent(39);Check(traffic.CanEnter(subject,stop),"clear NPC condition admission");var follower=new GameObject("Stopped following car");follower.layer=8;follower.AddComponent<BoxCollider>().size=new Vector3(1.8f,1.5f,4);var followerCar=follower.AddComponent<TrafficCar>();followerCar.route=new TrafficRoute{turn=-1};followerCar.route.SetPoints(new[]{trafficRoute.Position(0),trafficRoute.Position(39),trafficRoute.Position(39)+Vector3.left*20});followerCar.distance=33;follower.transform.position=trafficRoute.Position(33);follower.transform.forward=trafficRoute.Tangent(33);Physics.SyncTransforms();Check(traffic.CanEnter(subject,stop),"stationary follower behind approach does not block U-turn");UnityEngine.Object.DestroyImmediate(follower);var manualFollower=new GameObject("Stopped manual taxi behind approach");manualFollower.layer=8;manualFollower.AddComponent<Rigidbody>().isKinematic=true;manualFollower.AddComponent<BoxCollider>().size=new Vector3(1.8f,1.5f,4);manualFollower.AddComponent<TaxiController>();manualFollower.transform.position=trafficRoute.Position(33);manualFollower.transform.forward=trafficRoute.Tangent(33);Physics.SyncTransforms();Check(traffic.CanEnter(subject,stop),"stationary manual taxi behind approach does not block U-turn");UnityEngine.Object.DestroyImmediate(manualFollower);
 var blocker=new GameObject("Conflicting vehicle");blocker.layer=8;blocker.AddComponent<BoxCollider>().size=new Vector3(1.8f,1.5f,4);blocker.transform.position=join.points[32].V();Physics.SyncTransforms();Check(!traffic.CanEnter(subject,stop),"U-turn yields to occupied path even with protected left");UnityEngine.Object.DestroyImmediate(blocker);var conflicting=new GameObject("Opposing turning traffic");conflicting.layer=8;conflicting.transform.position=junction.center;conflicting.transform.forward=Vector3.back;conflicting.AddComponent<BoxCollider>();var otherCar=conflicting.AddComponent<TrafficCar>();otherCar.route=new TrafficRoute{turn=-1,direction=Vector3.back};Physics.SyncTransforms();Check(!traffic.YieldClear(junction,Vector3.forward,-2,subject.gameObject),"manual U-turn yields to opposing left-turn traffic");UnityEngine.Object.DestroyImmediate(conflicting);junction.rightTurnObservation=new RoadObservation{known=true,pedestrian=PedestrianState.Crossing};junction.observationAxis=0;junction.observationSign=1;Check(!traffic.CanEnter(subject,stop),"U-turn yields to crossing pedestrian observation");UnityEngine.Object.DestroyImmediate(subject.gameObject);junction.rightTurnObservation=null;traffic.manualTime=14;ObserverCase(traffic,junction,from,join);UnityEngine.Object.DestroyImmediate(root);
 MapCatalog.LockedRegion="eungye";MapCatalog.Load();var baseline=RoadMapRuntime.Baseline;var hash=RoadMapRuntime.Hash(baseline);var original=RoadMapDocument.Create(baseline);Check(RoadMapDocument.Parse(original.ToJson()).baseHash==hash&&RoadMapRuntime.Hash(baseline)==hash,"old map hash and document roundtrip");UturnMapObserverTests.Run();
 Debug.Log("UTURN_TESTS_OK geometry conditions validation routing glyph roundtrip");}
}
